import type { CSSProperties, ReactNode } from 'react';

import { SidebarInset, SidebarProvider } from '@/components/ui/sidebar';
import { TooltipProvider } from '@/components/ui/tooltip';

import { AppShellTrigger } from './app-shell-trigger';

// O w-72 do Admin One.
const SIDEBAR_WIDTH = { '--sidebar-width': '18rem' } as CSSProperties;

const MAIN_CONTENT_ID = 'main-content';

interface AppShellProps {
  // O AppSidebar, com a marca e o menu.
  sidebar: ReactNode;
  children: ReactNode;
  // O lado direito da barra superior, como o menu do usuário.
  actions?: ReactNode;
  // Menu aberto ou recolhido no desktop. O shadcn grava a escolha no cookie sidebar_state: ler no
  // servidor evita o menu piscar.
  defaultOpen?: boolean;
}

export function AppShell({ sidebar, children, actions, defaultOpen = true }: AppShellProps) {
  return (
    <TooltipProvider>
      <SidebarProvider defaultOpen={defaultOpen} style={SIDEBAR_WIDTH}>
        {/* Primeiro Tab da página: pula os itens do menu. Fica acima da tela até receber o foco. */}
        <a
          href={`#${MAIN_CONTENT_ID}`}
          className="fixed top-4 left-4 z-50 -translate-y-24 rounded-sm bg-card px-4 py-2 font-medium text-card-foreground shadow-lg outline-none focus:translate-y-0 focus-visible:ring-3 focus-visible:ring-ring"
        >
          Pular para o conteúdo
        </a>
        {sidebar}
        {/* O scroll-mt nos descendentes: ao voltar com Shift+Tab, o elemento focado para abaixo da
            barra fixa, e não embaixo dela. O min-w-0 deixa o conteúdo largo (uma tabela) rolar
            dentro do card: sem ele, a página inteira rola de lado entre 1024 e ~1160px. */}
        <SidebarInset
          id={MAIN_CONTENT_ID}
          tabIndex={-1}
          className="min-w-0 outline-none [&_*]:scroll-mt-18"
        >
          <header className="sticky top-0 z-10 flex h-14 shrink-0 items-center gap-2 bg-background px-3">
            <AppShellTrigger />
            <div className="flex-1" />
            {actions}
          </header>
          {children}
        </SidebarInset>
      </SidebarProvider>
    </TooltipProvider>
  );
}

'use client';

import { SidebarTrigger, useSidebar } from '@/components/ui/sidebar';

// O SidebarTrigger do shadcn não diz se o menu está aberto: o aria-expanded dá o estado ao leitor de
// tela, no desktop (menu recolhido) e no celular (a gaveta).
export function AppShellTrigger() {
  const { isMobile, open, openMobile } = useSidebar();
  let isExpanded = open;
  if (isMobile) {
    isExpanded = openMobile;
  }

  // No celular, o alvo tem 44px, o tamanho do polegar.
  return (
    <SidebarTrigger
      aria-expanded={isExpanded}
      className="size-11 text-foreground md:size-9 [&_svg]:size-5"
    />
  );
}

import type { ReactNode } from 'react';

import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader } from '@/components/ui/sidebar';

import { AppSidebarClose } from './app-sidebar-close';

interface AppSidebarProps {
  // A marca e, abaixo dela, o seletor de unidade, se o projeto tiver.
  header: ReactNode;
  // O menu: em geral o AppNavigation.
  children: ReactNode;
  // O fim do menu, como o "Sair".
  footer?: ReactNode;
}

// Sem o SidebarRail do shadcn: o Admin One não tem a faixa invisível na borda do menu, e ela é um
// alvo de 16px colado nos ícones do menu recolhido. O menu abre e recolhe pelo gatilho da barra.
// Sem o contorno de 1px do floating: o Admin One só tem a sombra.
export function AppSidebar({ header, children, footer }: AppSidebarProps) {
  return (
    <Sidebar
      variant="floating"
      collapsible="icon"
      className="**:data-[slot=sidebar-inner]:rounded-2xl **:data-[slot=sidebar-inner]:shadow-xl **:data-[slot=sidebar-inner]:ring-0"
    >
      {/* No celular, o pr-14 abre espaço para o X da gaveta. Recolhido, o menu tem 3rem: os recuos
          de aberto empurravam a marca e os ícones para fora do centro. */}
      <SidebarHeader className="relative gap-3 border-b border-sidebar-border px-3 py-4 group-data-[collapsible=icon]:px-1 in-data-[mobile=true]:pr-14">
        {header}
        <AppSidebarClose />
      </SidebarHeader>
      <SidebarContent className="px-2 py-2 group-data-[collapsible=icon]:px-0">
        {children}
      </SidebarContent>
      {footer !== undefined && (
        <SidebarFooter className="border-t border-sidebar-border px-2 py-3">{footer}</SidebarFooter>
      )}
    </Sidebar>
  );
}

'use client';

import { X } from 'lucide-react';

import { useSidebar } from '@/components/ui/sidebar';
import { Button } from '@/registry/frontend-ui/button/ui/button';

// A gaveta do celular cobre o gatilho da barra e só fechava com Esc ou tocando fora: o X dá a saída
// visível, como o mdiClose do menu do Admin One no tablet. No desktop o menu não é gaveta, e o X
// não aparece.
export function AppSidebarClose() {
  const { isMobile, setOpenMobile } = useSidebar();

  if (!isMobile) {
    return null;
  }

  return (
    <Button
      variant="ghost"
      size="icon"
      aria-label="Fechar menu"
      className="absolute top-3 right-3 size-11"
      onClick={() => {
        setOpenMobile(false);
      }}
    >
      <X />
    </Button>
  );
}

import type { ComponentType, ReactElement } from 'react';

import {
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar';

export interface NavigationItem {
  id: string;
  label: string;
  icon: ComponentType<{ className?: string }>;
  // Sem endereço, o item aparece apagado, com "Em breve": a tela ainda não existe.
  href: string | null;
}

export interface NavigationGroup {
  id: string;
  label: string | null;
  items: NavigationItem[];
}

interface AppNavigationProps {
  groups: NavigationGroup[];
  currentPath: string;
  // O link do framework (o Link do Next, por exemplo) com o href; o padrão é um <a>.
  renderLink?: (href: string) => ReactElement;
}

// O item ativo sem fundo: o ícone e o texto na marca, o texto em negrito e a barra da marca encostada
// no item, dentro do botão (o overflow-hidden do shadcn corta o que passa da borda dele).
const ITEM_CLASS =
  'relative h-11 gap-3 px-4 font-medium [&_svg]:size-[18px] [&_svg]:opacity-80 data-active:bg-transparent data-active:font-bold data-active:text-brand-muted-foreground data-active:hover:bg-sidebar-accent data-active:hover:text-brand-muted-foreground data-active:[&_svg]:opacity-100 data-active:before:absolute data-active:before:top-1/2 data-active:before:left-0 data-active:before:h-7 data-active:before:w-1 data-active:before:-translate-y-1/2 data-active:before:rounded-r-full data-active:before:bg-primary';

function renderAnchor(href: string): ReactElement {
  return <a href={href} />;
}

function withoutTrailingSlash(path: string): string {
  if (path.length > 1 && path.endsWith('/')) {
    return path.slice(0, -1);
  }
  return path;
}

// O item fica marcado na página dele e nas de dentro: /patients/new marca Pacientes. A raiz, só nela.
export function isCurrentPath(href: string, currentPath: string): boolean {
  const itemPath = withoutTrailingSlash(href);
  const path = withoutTrailingSlash(currentPath);
  if (itemPath === '/') {
    return path === '/';
  }
  return path === itemPath || path.startsWith(`${itemPath}/`);
}

export function AppNavigation({
  groups,
  currentPath,
  renderLink = renderAnchor,
}: AppNavigationProps) {
  return (
    <nav aria-label="Menu principal" className="flex flex-col">
      {groups.map((group) => (
        <SidebarGroup key={group.id} className="py-1">
          {group.label !== null && (
            // O text-sidebar-foreground/70 do shadcn fica abaixo do AA sobre o menu claro.
            <SidebarGroupLabel className="px-4 text-muted-foreground">
              {group.label}
            </SidebarGroupLabel>
          )}
          <SidebarGroupContent>
            {/* A linha clara entre os itens e o passo de 49px são os do menu do Admin One. */}
            <SidebarMenu className="gap-0 *:border-b *:border-sidebar-border/50 *:py-0.5 *:last:border-b-0">
              {group.items.map((item) => (
                <NavigationEntry
                  key={item.id}
                  item={item}
                  currentPath={currentPath}
                  renderLink={renderLink}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      ))}
    </nav>
  );
}

interface NavigationEntryProps {
  item: NavigationItem;
  currentPath: string;
  renderLink: (href: string) => ReactElement;
}

function NavigationEntry({ item, currentPath, renderLink }: NavigationEntryProps) {
  const Icon = item.icon;

  if (item.href === null) {
    return (
      <SidebarMenuItem>
        {/* Sem tooltip: o TooltipTrigger do Base UI não repassa o disabled ao botão. */}
        {/* O "em breve" vai no nome do botão, e o selo fica fora da árvore de acessibilidade: o
            leitor de tela ouve "Profissionais, em breve" uma vez só. */}
        <SidebarMenuButton
          disabled
          aria-label={`${item.label}, em breve`}
          className={`${ITEM_CLASS} pr-20`}
        >
          <Icon />
          <span>{item.label}</span>
        </SidebarMenuButton>
        <SidebarMenuBadge
          aria-hidden="true"
          className="peer-data-[size=default]/menu-button:top-3 right-2 rounded-full bg-muted px-2 font-normal text-sidebar-foreground"
        >
          Em breve
        </SidebarMenuBadge>
      </SidebarMenuItem>
    );
  }

  const isActive = isCurrentPath(item.href, currentPath);
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={isActive}
        tooltip={item.label}
        aria-current={isActive && 'page'}
        render={renderLink(item.href)}
        className={ITEM_CLASS}
      >
        <Icon />
        <span>{item.label}</span>
      </SidebarMenuButton>
    </SidebarMenuItem>
  );
}
